INSERT INTO `search_links` (`link_id`, `site_id`, `url`, `title`, `description`, `fulltxt`, `indexdate`, `size`, `md5sum`, `visible`, `level`) VALUES
(1,	1,	'http://www.doskivrn.ru/',	'Велес - пиломатериалы в Воронеже: доска в Воронеже, брус в Воронеже. Купить недорого любые доски и брус можно в Велес',	'Пиломатериалы в Воронеже: доска, брус, брусок. г. Воронеж',	'\n\n \n \n	\r\n\r\n\r\n\r\n\r\n \r\n\r\n \r\n \r\n  \r\n   \n \n	\n		\n			\n				\n					 \n				 \n				Велес  \n				\n					\n						\n							\n								 \r\n 	 О компании  \r\n 	 Каталог продукции  \r\n 	 Калькулятор  \r\n 	 Контакты  \r\n 	 Прайс-лист  \r\n 							 \n							  \n						 \n					 \n				 \n			 \n			\n				\n					\n						\n							\n								 Доска пола \n								 Доска поля является продуктом глубокой переработки древесины. Это изделие, имеющее влажность 10-12%, изготавливается на современном дерево-обрабатывающем оборудовании. Используется для чистовой отделки жилых помещений (квартир, домов, коттеджей). \n							 \n							\n								\n									 \n										 Доска пола является одним из старейших напольных покрытий. \n										 Посмотреть цены  \n									 \n									\n										\n									 \n								 \n							 \n						 \n						\n							\n								 Мебельный щит \n								 Мебельный щит является продуктом переработки натуральной древесины. Представляет собой щит, склеенный из сухих брусков одной категории, прошедших предварительную обработку. \n							 \n							\n								\n									 \n										 Используется при строительстве лестниц и других интерьерных элементов \n										 Посмотреть цены  \n									 \n									\n										\n									 \n								 \n							 \n						 \n						\n							\n								 Пиломатериалы \n								 Весь пиломатериал отличается плотностью натуральной древесины, правильной геометрией и соответствует ГОСТ 8486-86. \n							 \n							\n								\n									 \n										 Мы сотрудничаем с производителями пиломатериала из Северных регионов Российской Федерации \n										 Посмотреть цены  \n									 \n									\n										\n									 \n								 \n							 \n						 \n					 \n				 \n				\n					\n						\n							\n	\n		 on-line заявка \n		\n			 Воспользуйтесь on-line заявкой для быстрой связи с менеджером нашей компании.  \n		 \n	 \n	\n		 \n			\n				\n					\n						Ваше имя \n						 \n					 \n					\n						Компания \n						 \n					 \n				 \n				\n					\n						Телефон \n						 \n					 \n					\n						E-mail \n						 \n					 \n				 \n				\n					Сообщение \n					\n						 \n					 \n				 \n				\n					\n						 \n					 \n					\n						равно (цифрами) \n						 \n					 \n				 \n			 \n			Отправить \n		 \n	 \n 							\n								\n									\n										\n											 Калькулятор \n											\n												 Воспользуйтесь нашим специальным калькулятором для расчета стоимости \n											 \n											\n											открыть калькулятор \n										 \n									 \n									\n										 компания велес \n										\n											 \n	Компания &laquo;Велес&raquo; создана в 2004 году, в настоящее время является одним из ведущих поставщиков, осуществляющих комплексные поставки высококачественной продукции деревообработки на рынок Центрально-Черноземного региона. \n\n	\n		 \n	\n		 \n			В сферу деятельности компании входит комплектации крупных строительных объектов, а так же частного строительства полным ассортиментом пиломатериала и другими продуктами деревообработки. \n	 \n \n \n	Компания &laquo;Велес &raquo; предложит широкий ассортимент пиломатериала, от стандартных до индивидуальных размеров (как длина, так и ширина). \n \n	В целях обеспечения конкурентоспособности цен, компанией &laquo;Велес&raquo; заключены долгосрочные прямые договора с производителями из Северных регионов РФ. \n \n	Для удобства покупателей компания имеет два склада, что позволяет решать задачи по поставке пиломатериала в любой район города Воронеж. \n \n	На складах Компании предоставляется полный спектр предложенных услуг, оформление и комплектация заказов в максимально сжатые сроки. \n \n	Возможность использования различных форм расчета, гибкая система скидок и стабильно большой товарный запас продукции сделают договорной процесс максимально комфортным. \n \n	Взаимовыгодные партнерские отношения, оперативность и качество являются приоритетными принципами в работе с нашими клиентами и поставщиками. \n\n										 \n									 \n								 \n							 \n						 \n					 \n				 \n			 \n			\r\n	\r\n		\r\n			 \r\n				 г. Воронеж, ул. Антонова-Овсеенко, 9в, оф. 3 \r\n				 телефон:   +7 (473)  261-91-48  \r\n				 моб.:   8 (915)  545-32-24,  8 (952)  100-71-19  \r\n			 \r\n		 \r\n		создание сайта  \r\n		\r\n			\r\n				 \r\n					\r\n						\r\n							\r\n								\r\n							 \r\n						 \r\n						Искать \r\n					 \r\n					 введите слово для посика \r\n				 \r\n			 \r\n		 \r\n	 \r\n \r\n   \r		 \n	 \n \n \n ',	'2011-10-04',	12.25,	'00f06d53a3c1df600f05407a196fcc45',	0,	0),
