(6,	1,	'http://www.doskivrn.ru/pages/price/',	'Прайс-лист Велес',	'Прайс-лист Велес',	'\r\n\r\n \r\n \r\n	\r\n\r\n\r\n\r\n\r\n \r\n\r\n \r\n \r\n  \r\n   \r\n \r\n	\r\n		\r\n			  \r\n\r\n	Велес  \r\n	\r\n		\r\n			\r\n				\r\n					 \r\n 	 О компании  \r\n 	 Каталог продукции  \r\n 	 Калькулятор  \r\n 	 Контакты  \r\n 	Прайс-лист  \r\n 				 \r\n				  \r\n			 \r\n		 \r\n	 \r\n 			\r\n				\r\n										\r\n						\r\n							 Прайс-лист \r\n							\n	 \n		Доска обрезная \n	\n		\n			 \n		 \n			Всем известно, что деревянный пол не просто украшает любое помещение, он принимает на себя огромные нагрузки, которые со временем могут вызвать различные повреждения и тогда напольное покрытие нуждается в ремонте. Исправить положение может грамотно проведенный ремонт, который позволит еще долго наслаждаться прекрасным видом таких полов. \n	 \n	\n		\n			 \n				\n					Доска обрезная  25x100x6  (2 сорт)  6 500 руб./м 3   \n				 \n					Доска обрезная  25x150x6  ((2 сорт)  6 500 руб./м 3   \n				\n					Доска обрезная  100x100  (6м)  6 500 руб./м 3   \n				 \n					Доска обрезная  100x150  (6м)  6 500 руб./м 3   \n				\n					Доска обрезная  100x200  (6м)  6 500 руб./м 3   \n				 \n					Доска обрезная  150x150  (6м)  6 500 руб./м 3   \n				\n					Доска обрезная  25x100  (4м)  6 500 руб./м 3   \n				 \n					Доска обрезная  25x100  (64м)  6 500 руб./м 3   \n				\n					Доска обрезная  25x120  (3м)  6 500 руб./м 3   \n				 \n					Доска обрезная  25x120  (4м)  6 500 руб./м 3   \n				\n					Доска обрезная  25x120  (6м)  6 500 руб./м 3   \n				 \n					Доска обрезная  25x150  (3м)  6 500 руб./м 3   \n				\n					Доска обрезная  25x150  (4м)  6 500 руб./м 3   \n				 \n					Доска обрезная  25x150  (6м)  6 500 руб./м 3   \n				\n					Доска обрезная  25x200  (6м)  6 500 руб./м 3   \n			 \n		 \n		\n			 \n				 \n					Доска обрезная  30x100  (6м)  6 500 руб./м 3   \n				\n					Доска обрезная  30x150  (6м)  6 500 руб./м 3   \n				 \n					Доска обрезная  40x100  (6м)  6 500 руб./м 3   \n				\n					Доска обрезная  40x120  (6м)  6 500 руб./м 3   \n				 \n					Доска обрезная 4 0x150  (6м)  6 500 руб./м 3   \n				\n					Доска обрезная  50x100  (6м)  6 500 руб./м 3   \n				 \n					Доска обрезная  50x120  (6м)  6 500 руб./м 3   \n				\n					Доска обрезная  50x200  (6м)  6 500 руб./м 3   \n				 \n					Доска обрезная  75x150  (6м)  6 500 руб./м 3   \n			 \n		 \n	 \n \n\n	 \n		Доска необрезная \n	\n		\n			 \n		 \n			Всем известно, что деревянный пол не просто украшает любое помещение, он принимает на себя огромные нагрузки, которые со временем могут вызвать различные повреждения и тогда напольное покрытие нуждается в ремонте. Исправить положение может грамотно проведенный ремонт, который позволит еще долго наслаждаться прекрасным видом таких полов. \n	 \n	\n		\n			 \n				 \n					Доска необрезная  25мм  (4м, 6м, 8м)  3 200 руб./м 3   \n			 \n		 \n	 \n \n\n	 \n		Мебельный щит из дуба \n	\n		\n			 \n		 \n			 Порода дерева:  дуб черешчатый  Влажность : 6-8%\n			 Шлифование : зернистость 100 единиц  Клей : ЛИГНУМ КД  Шип : закрытый (мебельный с плечом)\n			 Скидки : от 15 щитов до 32 скидка  2% ; от 32 щитов до 65 скидка  4% ; от 65 щитов скидка  5%  + доставка бесплатно!\n			  \n	 \n	\n		\n			 \n				 Розничная цена за м 2   \n			 \n				\n					Щит дубовый  Сращенный  (АB 3000*600*18)   1 170 руб./м 2   \n				 \n					Щит дубовый   Сращенный   (АB 3000*600*40)  2 600 руб./м 2   \n				\n					Щит дубовый  Сращенный  (BB 3000*600*18)  1 161 руб./м 2   \n				 \n					Щит дубовый  Сращенный  (BB 3000*600*40)  2 470 руб./м 2   \n				\n					Щит дубовый   Сращенный   (BC 3000*600*18)   1 066 руб./м 2   \n				 \n					Щит дубовый   Сращенный   (BC 3000*600*40)     2 340 руб./м 2   \n				\n					Щит дубовый   Сращенный   (CC 3000*600*18)     906 руб./м 2   \n				 \n					Щит дубовый   Сращенный   (CC 3000*600*40)  2 210 руб./м 2   \n				\n					Щит дубовый   Цельноламильный   (АB до 2200*18)  1 604 руб./м 2   \n				 \n					Щит дубовый   Цельноламильный   (АB до 2200*18)  1 783 руб./м 2   \n				\n					Щит дубовый   Цельноламильный   (АB до 2200*40)  3 366 руб./м 2   \n				 \n					Щит дубовый  Цельноламильный  (АB до 2200*40)  3 760 руб./м 2   \n				\n					Щит дубовый  Цельноламильный  (BB до 2200*18)  1 515 руб./м 2   \n				 \n					Щит дубовый  Цельноламильный  (BB до 2200*18)  1 692 руб./м 2   \n				\n					Щит дубовый  Цельноламильный  (BB до 2200*40)  3 168 руб./м 2   \n				 \n					Щит дубовый  Цельноламильный  (BB до 2200*40)  3 564 руб./м 2   \n				\n					Щит дубовый  Цельноламильный  (АC до 2200*18)  1 337 руб./м 2   \n				 \n					Щит дубовый  Цельноламильный  (АC до 2200*18)  1 426 руб./м 2   \n				\n					Щит дубовый  Цельноламильный  (АC до 2200*40)  2 772 руб./м 2   \n				 \n					Щит дубовый  Цельноламильный  (АC до 2200*40)  2 970 руб./м 2   \n			 \n		 \n		\n			 \n				 Розничная цена за штуку  \n			 \n				\n					Щит дубовый  Сращенный  (АB 3000*600*18)   2 106 руб./шт  \n				 \n					Щит дубовый   Сращенный   (АB 3000*600*40)  4 680руб./шт  \n				\n					Щит дубовый  Сращенный  (BB 3000*600*18)  2 090 руб./шт  \n				 \n					Щит дубовый  Сращенный  (BB 3000*600*40)  4 446 руб./шт  \n				\n					Щит дубовый   Сращенный   (BC 3000*600*18)   1 944 руб./шт  \n				 \n					Щит дубовый   Сращенный   (BC 3000*600*40)     4 212 руб./шт  \n				\n					Щит дубовый   Сращенный   (CC 3000*600*18)     1 632 руб./шт  \n				 \n					Щит дубовый   Сращенный   (CC 3000*600*40)  3 978 руб./шт  \n				\n					Щит дубовый   Цельноламильный   (АB до 2200*18)  89 100 руб./м 3   \n				 \n					Щит дубовый   Цельноламильный   (АB до 2200*18)  99 000 руб./м 3   \n				\n					Щит дубовый   Цельноламильный   (АB до 2200*40)  84 150 руб./м 3   \n				 \n					Щит дубовый  Цельноламильный  (АB до 2200*40)  94 000 руб./м 3   \n				\n					Щит дубовый  Цельноламильный  (BB до 2200*18)  84 150 руб./м 3   \n				 \n					Щит дубовый  Цельноламильный  (BB до 2200*18)  94 000 руб./м 3   \n				\n					Щит дубовый  Цельноламильный  (BB до 2200*40)  79 200 руб./м 3   \n				 \n					Щит дубовый  Цельноламильный  (BB до 2200*40)  89 100 руб./м 3   \n				\n					Щит дубовый  Цельноламильный  (АC до 2200*18)  74 250 руб./м 3   \n				 \n					Щит дубовый  Цельноламильный  (АC до 2200*18)  79 200 руб./м 3   \n				\n					Щит дубовый  Цельноламильный  (АC до 2200*40)  69 300 руб./м 3   \n				 \n					Щит дубовый  Цельноламильный  (АC до 2200*40)  74 250 руб./м 3   \n			 \n		 \n	 \n \n\n	 \n		Доска пола \n	\n		\n			 \n		 \n			 Порода дерева:  сосна  Влажность : 12-14%. Цены оптовые. Опт от  35 м 3   \n		 \n			 Оптовые цены  \n	 \n	\n		\n			 \n				\n					Доска пола  (А 35*114*4000-6000 мм)  13 000 руб./м 3   \n				 \n					Доска пола  (B 35*114*4000-6000 мм)  11 000 руб./м 3   \n				\n					Доска пола  (А 27*114*4000-6000 мм)  13 000 руб./м 3   \n				 \n					Доска пола  (В 27*114*4000-6000 мм)  11 000 руб./м 3   \n			 \n		 \n		\n			 \n				 Розничная цена за штуку  \n			 \n				\n					Доска пола  (А 35*114*4000-6000 мм)  480 руб./м 2   \n				 \n					Доска пола  (А 27*114*4000-6000 мм)  380 руб./м 2   \n			 \n		 \n	 \n \n\r\n						 \r\n					 \r\n									 \r\n			 \r\n			\r\n	\r\n		\r\n			 \r\n				 г. Воронеж, ул. Антонова-Овсеенко, 9в, оф. 3 \r\n				 телефон:   +7 (473)  261-91-48  \r\n				 моб.:   8 (915)  545-32-24,  8 (952)  100-71-19  \r\n			 \r\n		 \r\n		создание сайта  \r\n		\r\n			\r\n				 \r\n					\r\n						\r\n							\r\n								\r\n							 \r\n						 \r\n						Искать \r\n					 \r\n					 введите слово для посика \r\n				 \r\n			 \r\n		 \r\n	 \r\n \r\n   \r		 \r\n	 \r\n \r\n \n ',	'2011-10-04',	20.53,	'4a93899b06a8567d5198baee84f4e44a',	0,	1);
